<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api, apiError, responseData } from '../../api'
import AdminState from '../../admin/AdminState.vue'

const route=useRoute(),booking=ref(null),loading=ref(false),working=ref(false),error=ref(''),status=ref(''),paymentAmount=ref('')
const money=value=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(value||0))
const balance=computed(()=>Number(booking.value?.total_amount??booking.value?.total??0)-Number(booking.value?.paid_amount??0))
async function load(){loading.value=true;error.value='';try{booking.value=responseData(await api.get(`/admin/bookings/${route.params.id}`));status.value=booking.value?.status;paymentAmount.value=Math.max(0,balance.value)}catch(err){error.value=apiError(err)}finally{loading.value=false}}
async function action(path,payload={}){working.value=true;error.value='';try{await api.post(`/admin/bookings/${route.params.id}/${path}`,payload);await load()}catch(err){error.value=apiError(err,'Không thể thực hiện nghiệp vụ.')}finally{working.value=false}}
async function updateStatus(){working.value=true;error.value='';try{await api.patch(`/admin/bookings/${route.params.id}/status`,{status:status.value});await load()}catch(err){error.value=apiError(err,'Không thể cập nhật trạng thái.')}finally{working.value=false}}
async function invoice(){working.value=true;try{const response=await api.get(`/admin/bookings/${route.params.id}/invoice`);const invoiceData=responseData(response);const blob=new Blob([JSON.stringify(invoiceData,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(err){error.value=apiError(err,'Không thể xuất hóa đơn.')}finally{working.value=false}}
onMounted(load)
</script>
<template><section><header class="admin-page-head"><div><router-link to="/admin/bookings">← Danh sách đặt phòng</router-link><h1>Chi tiết {{booking?.code??booking?.booking_code??route.params.id}}</h1><p>Trạng thái lưu trú, thanh toán và hóa đơn</p></div><button class="admin-button secondary" @click="invoice">Xuất hóa đơn</button></header><p v-if="error&&booking" class="admin-alert">{{error}}</p><AdminState :loading="loading" :error="error&&!booking?error:''" :empty="!loading&&!error&&!booking" @retry="load"/><div v-if="booking&&!loading" class="admin-detail-grid"><article class="admin-card"><header class="admin-panel-head"><h2>Thông tin đặt phòng</h2><span class="admin-badge" :class="booking.status">{{booking.status}}</span></header><div class="admin-panel-body"><dl class="admin-definition"><dt>Khách hàng</dt><dd>{{booking.guest_name}}</dd></dl><dl class="admin-definition"><dt>Liên hệ</dt><dd>{{booking.guest_phone}} · {{booking.guest_email}}</dd></dl><dl class="admin-definition"><dt>Khách sạn</dt><dd>{{booking.hotel?.name??booking.hotel_name}}</dd></dl><dl class="admin-definition"><dt>Phòng</dt><dd>{{booking.room?.number??booking.room_number??'Chưa xếp'}} · {{booking.room_type?.name??booking.room_type_name}}</dd></dl><dl class="admin-definition"><dt>Lưu trú</dt><dd>{{booking.check_in??booking.checkin}} → {{booking.check_out??booking.checkout}}</dd></dl><dl class="admin-definition"><dt>Số khách</dt><dd>{{booking.adults??0}} người lớn, {{booking.children??0}} trẻ em</dd></dl><dl class="admin-definition"><dt>Ghi chú</dt><dd>{{booking.note??'Không có'}}</dd></dl></div></article><aside><article class="admin-card" style="margin-bottom:18px"><header class="admin-panel-head"><h2>Nghiệp vụ lễ tân</h2></header><div class="admin-panel-body"><label class="admin-field"><span>Trạng thái</span><select v-model="status" class="admin-select"><option v-for="item in ['pending','confirmed','checked_in','checked_out','cancelled']" :key="item">{{item}}</option></select></label><button class="admin-button" style="width:100%;margin-top:10px" :disabled="working" @click="updateStatus">Cập nhật trạng thái</button><div class="admin-actions" style="margin-top:10px"><button class="admin-button secondary" style="flex:1" :disabled="working" @click="action('check-in')">Check-in</button><button class="admin-button secondary" style="flex:1" :disabled="working" @click="action('check-out')">Check-out</button></div></div></article><article class="admin-card"><header class="admin-panel-head"><h2>Thanh toán</h2><span class="admin-badge" :class="booking.payment_status">{{booking.payment_status??'unpaid'}}</span></header><div class="admin-panel-body admin-stat-list"><div class="admin-stat-line"><span>Tổng tiền</span><b>{{money(booking.total_amount??booking.total)}}</b></div><div class="admin-stat-line"><span>Đã trả</span><b>{{money(booking.paid_amount)}}</b></div><div class="admin-stat-line"><span>Còn lại</span><b>{{money(balance)}}</b></div><label class="admin-field"><span>Thu thêm tiền mặt</span><input v-model="paymentAmount" class="admin-input" type="number" min="0"/></label><button class="admin-button" :disabled="working||!Number(paymentAmount)" @click="action('payments',{amount:Number(paymentAmount),method:'cash'})">Ghi nhận thanh toán</button></div></article></aside></div></section></template>
